+fn cut_with(start: PassStart, p: &PocketParams) -> Toolpath {
+    let (stock, band) = dog_bone();
+    let side = StartSide { start, stock: Some(stock), around_part: true };
+    match pocket_started_on(&band, p, &[], &CornerRelief::default(), &side) {
+        Ok(t) => t,
